def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal color bands: extend the nearest band into blank rows.
    if all(len({v for v in row if v}) <= 1 for row in grid):
        rowcolors = [next((v for v in row if v), 0) for row in grid]
        known = [r for r, v in enumerate(rowcolors) if v]
        for r in range(h):
            if not rowcolors[r]:
                k = min(known, key=lambda x: abs(x-r))
                rowcolors[r] = rowcolors[k]
        return [[rowcolors[r]] * w for r in range(h)]

    # Extend the diagonal stripes periodically, using their offsets.
    by_offset = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                by_offset[c-r] = grid[r][c]

    period = len(by_offset)
    phases = {}
    for off, color in by_offset.items():
        phases[off % period] = color

    # Fill any phases not explicitly represented by continuing the offset order.
    ordered = sorted(by_offset)
    for phase in range(period):
        if phase not in phases:
            phases[phase] = by_offset[ordered[phase % len(ordered)]]

    return [[phases[(c-r) % period] for c in range(w)] for r in range(h)]
