                stripes[d] = grid[r][c]

    # The marked diagonals define one repeating color cycle, in offset order.
    offsets = sorted(stripes)
    cycle = [stripes[d] for d in offsets]
    period = len(cycle)
    start = offsets[0]
    return [
        [cycle[(c - r - start) % period] for c in range(w)]
