def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each marked down-right diagonal identifies a color at its c-r offset.
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[c-r] = grid[r][c]

    # Order the distinct marked colors by their diagonal offsets. The gaps
    # between the marks are the unshown portion of the repeating pattern.
    offsets = sorted(marks)
    cycle = []
    for d in offsets:
        if marks[d] not in cycle:
            cycle.append(marks[d])

    # Anchor the cycle to a known stripe and extend it periodically.
    anchor = offsets[0]
    first = marks[anchor]
    phase = cycle.index(first)
    return [[cycle[(phase + (c-r-anchor)) % len(cycle)] for c in range(w)]
            for r in range(h)]
